      {bottomTab==='orders'&&<><PortfolioTable title="No orders." rows={portfolio.orders||[]} cols={['Instrument','Side','Qty','Type','Status']} map={(o:any)=>[o.symbol||o.instrument_token,o.side,o.quantity,o.orderType||o.type,o.status]}/><button className="tc4-btn" style={{marginTop:8}} onClick={()=>void sync()}><RefreshCw size={12}/>Refresh</button></>}
